# Unit test for method get_style_class of class ColorFormatter
def test_ColorFormatter_get_style_class(monkeypatch):
    class TestStyle(pygments.style.Style):
        styles = {}

    def mock_get_style_by_name(name):
        if name == 'test-style':
            return TestStyle
        raise ClassNotFound(name)

    monkeypatch.setattr(
        pygments.styles,
        'get_style_by_name',
        mock_get_style_by_name,
    )

    # Returns the style resolved by Pygments.
    assert ColorFormatter.get_style_class('test-style') is TestStyle

    # Falls back to the bundled Solarized style when resolution fails.
    assert (
        ColorFormatter.get_style_class('unknown-style')
        is Solarized256Style
    )
